with source as (select * from {{ source('spectrum_processed','olist_order_payments_parquet') }})
select nullif(trim(order_id),'') order_id,try_cast(nullif(trim(payment_sequential),'') as integer) payment_sequential,lower(nullif(trim(payment_type),'')) payment_type,try_cast(nullif(trim(payment_installments),'') as integer) payment_installments,try_cast(nullif(trim(payment_value),'') as decimal(18,2)) payment_value,nullif(trim(source_file_name),'') source_file_name,try_cast(nullif(trim(ingested_at),'') as timestamp) ingested_at,try_cast(nullif(trim(run_date),'') as date) run_date from source
